<?php declare(strict_types=1); $money=static fn(int $v):string=>number_format($v,0,',','.').' ₫'; ?>
<header class="resource-header"><div><span class="booking-eyebrow">Revenue reconciliation</span><h1>Đối soát doanh thu</h1><p>Tạo snapshot từ các hóa đơn đã phát hành, kiểm tra rồi chốt kỳ cho từng cơ sở.</p></div></header>
<section class="resource-surface settlement-create"><header class="resource-card-heading"><h2>Tạo kỳ đối soát</h2><p>Ngày được tính theo thời điểm phát hành hóa đơn (UTC).</p></header><form class="resource-toolbar report-filter" method="post" action="<?= $baseUrl ?>/partner/settlements"><input type="hidden" name="_token" value="<?= $csrfToken ?>"><label class="field"><span>Cơ sở</span><select name="propertyId" required><option value="">Chọn cơ sở</option><?php foreach($properties as $property):?><option value="<?= $property['id'] ?>"><?= htmlspecialchars($property['name'],ENT_QUOTES,'UTF-8') ?></option><?php endforeach;?></select></label><label class="field"><span>Từ ngày</span><input type="date" name="from" value="<?= $defaultFrom ?>" required></label><label class="field"><span>Đến ngày</span><input type="date" name="to" value="<?= $defaultTo ?>" required></label><button class="button button--primary" type="submit">Tạo bản nháp</button></form></section>
<section class="resource-surface"><header class="resource-card-heading"><h2>Các kỳ gần đây</h2><p>Bản nháp có thể cập nhật; kỳ đã chốt giữ nguyên snapshot.</p></header><div class="resource-table-wrap"><table class="resource-table"><thead><tr><th>Kỳ</th><th>Cơ sở</th><th>Trạng thái</th><th>Booking</th><th>Doanh thu thuần</th><th></th></tr></thead><tbody><?php if($settlements===[]):?><tr><td colspan="6" class="empty-cell">Chưa có kỳ đối soát.</td></tr><?php endif;?><?php foreach($settlements as $item):?><tr><td><strong><?= $item->from ?></strong> → <?= $item->to ?></td><td><?= htmlspecialchars($item->propertyName,ENT_QUOTES,'UTF-8') ?></td><td><span class="status-pill <?= $item->status==='FINALIZED'?'status-pill--success':'status-pill--warning' ?>"><?= $item->status==='FINALIZED'?'Đã chốt':'Bản nháp' ?></span></td><td><?= $item->bookingCount ?></td><td><strong><?= $money($item->netRevenue->amount()) ?></strong></td><td><a class="button button--secondary button--small" href="<?= $baseUrl ?>/partner/settlements/<?= $item->id ?>">Xem</a></td></tr><?php endforeach;?></tbody></table></div></section>
